function topScores(scores, n) {
  // scores: array of numbers from the leaderboard service
  const valid = scores.filter((s) => Number.isFinite(s));
  const sorted = [...valid].sort();
  return sorted.slice(-n).reverse();
}

function rankOf(scores, mine) {
  return topScores(scores, scores.length).indexOf(mine) + 1;
}

